}

// exec updates the row and its edges, in one transaction, or returns a
// `NotFoundError`.
pub fn (b CommentUpdateOne) exec() ! {
	if !b.graph.client.update_one(b.data)! {
		return NotFoundError{
			table: 'comments'
		}
	}
}

