// exec deletes the rows, with their join table rows, in one transaction, and
// returns how many there were.
pub fn (b CommentDelete) exec() !int {
	return b.graph.client.delete(b.data)
}

// comments_by_keys returns the rows with the keys `keys`, in their order.
fn (g Graph) comments_by_keys(keys []string) ![]CommentNode {
	// as stored: no privacy rule or interceptor hides a row just written
	rows := Graph{
		client: g.client.bypass()
	}.comments().where(load.in_keys('id', keys, .i64)).all()!
	mut by_key := map[string]CommentNode{}
	for row in rows {
		by_key[row.comment.id.str()] = row
	}
	mut found := []CommentNode{cap: keys.len}
	for key in keys {
		found << by_key[key] or {
			return NotFoundError{
				table: 'comments'
			}
		}
	}
	return found
}

// CreateCommentInput is what a create of a `comments` row sets, as the GraphQL input
// `CreateCommentInput` gives it: `none` and empty lists leave things as
// they are.
pub struct CreateCommentInput {
pub mut:
	user_id    ?i64
	owner_type ?string
	owner_id   ?i64
	parent_id  ?i64
	body       ?string
}

// set_input sets what `input` gives: clears first, then values, then edges.
pub fn (b CommentCreate) set_input(input CreateCommentInput) CommentCreate {
	mut next := b
	if v := input.user_id {
		next = next.set_user_id(v)
	}
	if v := input.owner_type {
		next = next.set_owner_type(v)
	}
	if v := input.owner_id {
		next = next.set_owner_id(v)
	}
	if v := input.parent_id {
		next = next.set_parent_id(v)
	}
	if v := input.body {
		next = next.set_body(v)
	}
	return next
}

// UpdateCommentInput is what a update of a `comments` row sets, as the GraphQL input
